files.macros/cents_to_units.sql:
{#- Convert an integer amount in cents into currency units (2 decimals). -#}
{% macro cents_to_units(column_name, scale=2) -%}
    cast({{ column_name }} / 100 as decimal(18, {{ scale }}))
{%- endmacro %}

files.macros/convert_to_eur.sql:
{#-
    Multiply an amount by an exchange rate and round to cents.
    The parentheses matter: the macro pastes TEXT, so convert_to_eur('a - b')
    must become (a - b) * rate, not a - b * rate.
-#}
{% macro convert_to_eur(amount, rate_column='rate_to_eur') -%}
    round(({{ amount }}) * {{ rate_column }}, 2)
{%- endmacro %}

files.macros/generate_schema_name.sql:
{#-
    dev / ci : every model goes to the target schema (dbt_adnane, ci...)
    prod     : a model with a custom schema goes to that schema (staging, finance...)
-#}
{% macro generate_schema_name(custom_schema_name, node) -%}
    {%- if target.name == 'prod' and custom_schema_name is not none -%}
        {{ custom_schema_name | trim }}
    {%- else -%}
        {{ target.schema }}
    {%- endif -%}
{%- endmacro %}

files.macros/profile_key.sql:
{#-
    dbt run-operation profile_key --args '{source_name: web_analytics, table_name: events, key: event_id}'
    Prints the number of rows, distinct keys and duplicated keys of a source table.
-#}
{% macro profile_key(source_name, table_name, key) %}
    {% set relation = source(source_name, table_name) %}
    {% set sql %}
        select count(*) as n_rows,
               count(distinct {{ key }}) as n_keys,
               count(*) - count(distinct {{ key }}) as n_duplicates
        from {{ relation }}
    {% endset %}
    {% set row = run_query(sql).rows[0] %}
    {{ log(relation ~ ': ' ~ row['n_rows'] ~ ' rows, ' ~ row['n_keys'] ~ ' distinct ' ~ key
           ~ ', ' ~ row['n_duplicates'] ~ ' duplicates', info=True) }}
{% endmacro %}

files.models/marts/marketing/_marketing__unit_:
unit_tests:
  - name: test_cancelled_orders_do_not_count
    description: >
      number_of_orders and lifetime_value_eur ignore cancelled orders.
      A returned order counts as an order, but its net value is 0.
      A customer without orders gets 0 (not NULL).
    model: dim_customers
    given:
      - input: ref('stg_shopflow_app__customers')
        rows:
          - {customer_id: 1, email: lina@example.com, country_code: MA}
          - {customer_id: 2, email: null, country_code: FR}
      - input: ref('country_regions')
        rows:
          - {country_code: MA, country_name: Morocco, region: Africa}
          - {country_code: FR, country_name: France, region: Europe}
      - input: ref('int_orders__enriched')
        rows:
          - {order_id: 10, customer_id: 1, order_at: 2025-09-01 10:00:00, order_status: delivered, net_amount_eur: 120.50}
          - {order_id: 11, customer_id: 1, order_at: 2025-10-05 18:00:00, order_status: returned, net_amount_eur: 0.00}
          - {order_id: 12, customer_id: 1, order_at: 2025-11-20 09:00:00, order_status: cancelled, net_amount_eur: 0.00}
    expect:
      rows:
        - {customer_id: 1, region: Africa, first_order_at: 2025-09-01 10:00:00, last_order_at: 2025-10-05 18:00:00, number_of_orders: 2, lifetime_value_eur: 120.50}
        - {customer_id: 2, region: Europe, first_order_at: null, last_order_at: null, number_of_orders: 0, lifetime_value_eur: 0}

